content.text:
{
  "name": "罗德与施瓦茨 ZNB20 矢量网络分析仪",
  "name_en": "Rohde & Schwarz ZNB20 Vector Network Analyzer",
  "manufacturer": "Rohde & Schwarz",
  "description": "用于对微波器件和射频网络进行扫频测试的矢量网络分析仪，可读取扫频频率点以及复数或格式化的测量数据，常用于 S 参数表征。",
  "description_en": "A vector network analyzer for swept-frequency testing of microwave devices and RF networks. It can read sweep stimulus points and complex or formatted measurement data, and is commonly used for S-parameter characterization.",
  "actions": [
    {
      "action_name": "auto-get_stimulus",
      "description": "获取扫频使用的频率点",
      "description_en": "get the frequencies used in the sweep"
    },
    {
      "action_name": "auto-get_real_imaginary_data",
      "description": "获取测量数据的实部和虚部",
      "description_en": "get the real and imaginary parts of the measurement data"
    },
    {
      "action_name": "auto-get_formatted_data",
      "description": "获取格式化的测量数据",
      "description_en": "get the formatted measurement data"
    }
  ],
  "tag_hints": [
    "vector network analyzer",
    "S-parameter measurement",
    "frequency sweep",
    "microwave characterization",
    "complex trace data",
    "RF test"
  ]
}

